private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (true) {
        int byteValue = bb.get(i);
        if (byteValue < 0) {
            // If the byte is negative, it's a UTF-8 continuation byte.
            byte continuationByte = (byte) (byteValue & 0x3F);
            sb.append((char) (byteValue << 8 | continuationByte));
            i++;
            continue;
        }
        int utf16CodeUnit = (byteValue >> 4) & 0x1F;
        if (utf16CodeUnit == 0xF) {
            // This is a high-surrogate part, with a next continuation byte.
            byte continuationByte = (byte) (bb.get(i) & 0x3F);
            sb.append((char) (((utf16CodeUnit & 0xF) << 10) | continuationByte + 0xD800));
            i+=2;
            continue;
        }
        sb.append((char) utf16CodeUnit);
        i++;
        break;
    }
    return i;
}
