    for (int idx = 0; idx < numLeft; idx++) {
        String key = Objects.requireNonNull(resultMap.keySet().toArray(new String[0]))[idx];
        V left = resultMap.get(key); // first split key values from the map
        String key1 = Objects.requireNonNull(resultMap.keySet().toArray(new String[0]))[resultMap.size() - 1 - idx];
        V right = resultMap.get(key1); // second split key values from the map
        target.addEdge(left, right, (E)null);
        resultMap.remove(key1);
        resultMap.remove(key);
        numLeft --;
    }
}
