public class TimeRangeBuilder {
    private static final long FETCH_DATA_DURATION = 24 * 60 * 60 * 1000; // 1 day in milliseconds

    public List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        while (start < end) {
            long startTime = start;
            long endTime = start + FETCH_DATA_DURATION;
            if (endTime > end) {
                endTime = end;
            }
            if (startTime < endTime) {
                timeRanges.add(new TimeRange(startTime, endTime));
            }
            start = endTime;
        }
        return timeRanges;
    }

    private static class TimeRange {
        private long startTime;
        private long endTime;

        public TimeRange(long startTime, long endTime) {
            this.startTime = startTime;
            this.endTime = endTime;
        }

        @Override
        public String toString() {
            return "TimeRange{" +
                    "startTime=" + startTime +
                    ", endTime=" + endTime +
                    '}';
        }
    }
}
