public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Hanlde absolute and relative URIs
    String path = u.getPath();
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    // Split the path by '/'
    String[] segments = path.split("/");

    List<PathSegmentImpl> result = new java.util.ArrayList<>();
    for (String segment : segments) {
        if (decode) {
            result.add(pathSegmentImpl.decode(segment));
