     * Split a box along the x axis into two equal boxes.
     * @param box the box to split
     * @return a pair with the two resulting boxes
     */
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        double halfWidth = box.getWidth() / 2;
        Rectangle2D leftBox = new Rectangle2D.Double(box.getMinX(), box.getMinY(), halfWidth, box.getHeight());
        Rectangle2D rightBox = new Rectangle2D.Double(box.getMinX() + halfWidth, box.getMinY(), box.getWidth() - halfWidth, box.getHeight());
        return Pair.with(leftBox, rightBox);
    }
