public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < length) {
            char next = str.charAt(i + 1);
            if (next == 't') {
                sb.append('\t');
                i++; // Skip the next character after tab
            } else if (next == 'n') {
                sb.append('\n');
                i++; // Skip the next character after newline
            } else {
                sb.append('\\');
                sb.append(next);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
