private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph.vertices().size() != vertices.size() || vertices.isEmpty()) {
        return false;
    }

    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1.equals(vertex2) || !graph.hasEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

